 public static void Run(Action<bool,string> check,bool route=true)
 {
  var d=CampaignLoader.Load(CampaignLoader.BundledEquipmentPath);string path=Path.Combine(Path.GetTempPath(),"zombie-equipment-"+Guid.NewGuid()+".json");
