  w=Fresh();a=w.PartyLeader;Equip(w,"item.ranged.006");Give(w,"item.ammo.catalogue-bolt",4);var gun=a.Equipment.Weapon!;check(w.ReloadFirearm(a)&&gun.LoadedAmmunition!.Quantity==1&&a.Inventory.Count("item.ammo.catalogue-bolt")==3,"Phase 18 manual crossbow loads exactly one physical bolt");
  w.Save(path);w=World.Load(path);a=w.PartyLeader;check(w.UnloadFirearm(a)&&a.Inventory.Count("item.ammo.catalogue-bolt")==4&&a.Equipment.Weapon!.LoadedAmmunition==null,"Phase 18 unloading after reload restores the same ammunition count");
  a.Inventory.Items.RemoveAll(s=>s.ItemId=="item.ammo.catalogue-bolt");Give(w,"item.mall.ammo-9mm");identity=w.NextItemInstanceNumber;check(!w.ReloadFirearm(a)&&w.NextItemInstanceNumber==identity,"Phase 18 incompatible calibre cannot enter the magazine");
  w=Fresh();a=w.PartyLeader;Equip(w,"item.melee.008");check(a.Equipment.Weapon!.Definition.Equipment!.Critical==19&&a.AttackDamageType==DamageType.Slashing,"Phase 18 source critical range and damage type reach the physical weapon");
  w=Fresh();a=w.PartyLeader;var filter=Give(w,"item.commodity.067");Give(w,d.Infrastructure!.DirtyWaterItemId,2);int xp=w.ResourceXpAwarded;int water=a.Inventory.Count(d.Infrastructure.CleanWaterItemId);check(filter.Charges==5&&w.UseEquipment(a,filter.InstanceId)&&filter.Charges==4&&a.Inventory.Count(d.Infrastructure.CleanWaterItemId)==water+1,"Phase 18 portable filter spends one dirty water and one of five charges");
  check(a.Inventory.Count(d.Infrastructure.DirtyWaterItemId)==1&&w.ResourceXpAwarded==xp&&a.Inventory.Items.Where(s=>s.ItemId==d.Infrastructure.CleanWaterItemId).All(s=>s.ResourceUnits.Count==0),"Phase 18 water conversion grants no extra scavenging tokens or XP");
  w.Save(path);w=World.Load(path);a=w.PartyLeader;filter=a.Inventory.Items.Single(s=>s.ItemId=="item.commodity.067");check(filter.Charges==4&&w.UseEquipment(a,filter.InstanceId)&&filter.Charges==3,"Phase 18 filter charge and water consumption survive reload");
  w=Fresh();a=w.PartyLeader;var light=Give(w,"item.commodity.036");identity=w.NextItemInstanceNumber;check(!w.UseEquipment(a,light.InstanceId)&&w.NextItemInstanceNumber==identity,"Phase 18 flashlight without battery is rejected before cost");Give(w,"item.commodity.037",2);check(w.UseEquipment(a,light.InstanceId)&&a.Inventory.Count("item.commodity.037")==1&&w.EquipmentLitCell(a.Pos),"Phase 18 physical battery powers a known-floor light");check(!w.UseEquipment(a,light.InstanceId)&&a.Inventory.Count("item.commodity.037")==1,"Phase 18 already operating light cannot spend another battery");w.AdvanceCampaignSeconds(60);w.Save(path);w=World.Load(path);check(w.EquipmentEffects.Single().Expires>w.CampaignMinutes*60d+w.CampaignSeconds+1700,"Phase 18 light retains remaining campaign duration");w.AdvanceCampaignSeconds(1740);check(w.EquipmentEffects.Count==0,"Phase 18 light expires after thirty campaign minutes");
