  w=Fresh();a=w.PartyLeader;var bomb=Give(w,"item.explosive.004");int hp=a.Hp;check(w.UseEquipment(a,bomb.InstanceId,cell:a.Pos)&&a.Hp<hp&&a.Inventory.Count(bomb.ItemId)==0,"Phase 18 blast uses source damage and can harm its owner");
