  var s0=w.Features.Single(f=>f.Id=="feature.mall.equipment-cache");check(s0.Contents.Items.Sum(s=>s.Quantity*d.Items.Single(i=>i.Id==s.ItemId).ResourceSv)==203&&s0.Contents.Items.All(s=>s.ResourceUnits.Count==s.Quantity),"Phase 18 authored cache has exactly 203 SV with per-unit provenance");
  w.Save(path);string original=File.ReadAllText(path);
  void Reject(Action<JsonNode> mutate,string reason){var n=JsonNode.Parse(original)!;mutate(n);File.WriteAllText(path,n.ToJsonString());bool rejected=false;try{World.Load(path);}catch{rejected=true;}check(rejected,"Phase 18 rejects "+reason);}
  Reject(n=>n["EquipmentEffects"]!.AsArray().Add(new JsonObject{["Kind"]="light",["ActorId"]="unknown",["AreaId"]=w.CurrentTravelDestinationId,["ItemId"]="item.commodity.036",["Cell"]=new JsonObject{["X"]=12,["Y"]=27},["RadiusFeet"]=15,["Expires"]=w.CampaignMinutes*60+10}),"unowned saved light");
  Reject(n=>n["EquipmentMines"]!.AsArray().Add(new JsonObject{["OwnerId"]=a.Id,["AreaId"]=w.CurrentTravelDestinationId,["ItemId"]="item.commodity.036",["Cell"]=new JsonObject{["X"]=12,["Y"]=26}}),"light masquerading as mine");
  var old=World.New(CampaignLoader.Load(CampaignLoader.BundledClassesPath));old.Save(path);var legacy=JsonNode.Parse(File.ReadAllText(path))!;legacy["Version"]=30;legacy.AsObject().Remove("EquipmentEffects");legacy.AsObject().Remove("EquipmentMines");File.WriteAllText(path,legacy.ToJsonString());old=World.Load(path);check(old.Version==World.CurrentSaveVersion&&!old.EquipmentEnabled&&old.Campaign!.Items.Count==20,"Phase 18 v30 migration preserves original campaign and gear without catalogue injection");
  foreach(var bad in new[]{"status","critical","source","ammo-pack","schema","mine-reference"})
  {var copy=CampaignLoader.Clone(d);var item=copy.Items.Single(i=>i.Id=="item.ranged.006");switch(bad){case "status":item.Equipment!.Status="invented";break;case "critical":item.Equipment!.Critical=1;break;case "source":item.Equipment!.SourceCells["bad"]=new string('x',2001);break;case "ammo-pack":item.Equipment!.Use="ammo-pack";item.Equipment.PackAmmoId="not-ammo";item.Equipment.PackQuantity=999;break;case "schema":copy.SchemaVersion=15;break;case "mine-reference":item.Equipment!.Status="reference";item.Equipment.Use="mine";break;}check(CampaignLoader.Validate(copy).Count>0,"Phase 18 invalid catalogue definition rejected: "+bad);}
  w=Fresh();a=w.PartyLeader;var hand=Give(w,"item.commodity.049");int minute=w.CampaignMinutes;check(w.UseEquipment(a,hand.InstanceId)&&w.CampaignMinutes==minute+1&&a.Inventory.Count(hand.ItemId)==1,"Phase 18 hand-crank light costs one minute, not a battery or the reusable tool");
  w=Fresh();a=w.PartyLeader;filter=Give(w,"item.commodity.067");Give(w,d.Infrastructure!.DirtyWaterItemId);a.Inventory.MaxSlots=a.Inventory.Items.Count;identity=w.NextItemInstanceNumber;int dirtyBefore=a.Inventory.Count(d.Infrastructure.DirtyWaterItemId);string denied=w.EquipmentUseReason(a,filter.InstanceId);if(denied!="")check(!w.UseEquipment(a,filter.InstanceId)&&filter.Charges==5&&w.NextItemInstanceNumber==identity&&a.Inventory.Count(d.Infrastructure.DirtyWaterItemId)==dirtyBefore,"Phase 18 rejected purification is atomic");else check(w.UseEquipment(a,filter.InstanceId),"Phase 18 purification may reuse the consumed dirty-water slot");
  w=Fresh();a=w.PartyLeader;var kit=Give(w,"item.commodity.027");a.Hp-=10;check(w.UseEquipment(a,kit.InstanceId)&&kit.Charges==4&&kit.Quantity==1,"Phase 18 medical use consumes the selected catalogue kit charge");w.Save(path);w=World.Load(path);check(w.PartyLeader.Inventory.Items.Single(s=>s.ItemId=="item.commodity.027").Charges==4,"Phase 18 selected medical kit cannot refresh through saving");
  w=Fresh();a=w.PartyLeader;var flash=Give(w,"item.explosive.007");check(w.UseEquipment(a,flash.InstanceId,cell:a.Pos)&&a.Inventory.Count(flash.ItemId)==0&&w.EquipmentEffects.All(e=>e.Kind=="blind"),"Phase 18 flash checks saves and spends a real bomb");w.AdvanceCampaignSeconds(12);check(w.EquipmentEffects.Count==0,"Phase 18 all flash effects expire after two rounds");
  w=Fresh();a=w.PartyLeader;Equip(w,"item.ranged.006");Give(w,"item.ammo.catalogue-bolt",4);w.ReloadFirearm(a);enemy=w.Actors.First(t=>t.Enemy);enemy.Pos=new(12,26);enemy.Hp=enemy.MaxHp=200;w.Reveal();w.StartCombat(enemy.Group);w.Order=[a.Id,enemy.Id];w.Turn=0;a.Economy.Reset(a.EffectiveSpeedFeet,1);check(w.Attack(a,enemy,AttackKind.Basic)&&a.Equipment.Weapon!.LoadedAmmunition==null&&a.Inventory.Count("item.ammo.catalogue-bolt")==3,"Phase 18 real crossbow attack spends one loaded bolt on hit or miss");check(!w.Attack(a,enemy,AttackKind.Basic),"Phase 18 empty manual weapon cannot attack again");
  w=Fresh();a=w.PartyLeader;Equip(w,"item.melee.008");enemy=w.Actors.First(t=>t.Enemy);enemy.Pos=new(12,26);enemy.Hp=enemy.MaxHp=10000;enemy.BaseAc=1;w.Reveal();w.StartCombat(enemy.Group);w.Order=[a.Id,enemy.Id];w.Turn=0;int critBefore=a.Statistics.CriticalHits;for(int n=0;n<100;n++){a.Economy.Reset(a.EffectiveSpeedFeet,1);w.Attack(a,enemy,AttackKind.Basic);}check(a.Statistics.CriticalHits>critBefore&&a.Statistics.AttacksMade==100,"Phase 18 source critical weapon resolves repeated real attacks and damage");
  w=Fresh();a=w.PartyLeader;var shield=d.Items.First(i=>i.Kind==ItemKind.Shield);Equip(w,shield.Id);var twoHand=d.Items.First(i=>i.Kind==ItemKind.Weapon&&i.Equipment is {TwoHanded:true,Status:"standard"}&&i.Weight<20);var two=Give(w,twoHand.Id);check(!w.Equip(a,a.Inventory.Items.IndexOf(two)),"Phase 18 two-handed source weapon respects the occupied offhand");
  w=Fresh();a=w.PartyLeader;var impossible=Give(w,"item.explosive.004");identity=w.NextItemInstanceNumber;minute=w.CampaignMinutes;hp=a.Hp;check(!w.UseEquipment(a,impossible.InstanceId,cell:new(0,0))&&a.Inventory.Count(impossible.ItemId)==1&&w.NextItemInstanceNumber==identity&&a.Hp==hp&&w.CampaignMinutes==minute,"Phase 18 invalid blast placement spends no item, HP, identity or time");
  w=Fresh();a=w.PartyLeader;var recovered=w.Party.Skip(1).First();recovered.Position=a.Position+new WorldPoint(.2f,.3f);var away=a.Position+new WorldPoint(-1,0);check(w.SegmentClear(a.Position,away,a)&&w.MoveTo(a,away),"Phase 18 recovered overlapping allies can walk apart without teleporting");for(int n=0;n<100&&w.IsMoving(a);n++)w.UpdateMovement(.02f);check(a.Position.Distance(away)<.01f&&a.Position.Distance(recovered.Position)>World.BodyRadius*2,"Phase 18 physical movement separates recovered bodies");
  a.Position=new(12.5f,27.5f);recovered.Position=a.Position+new WorldPoint(.2f,.3f);check(!w.SegmentClear(a.Position,recovered.Position,a)&&!w.SegmentClear(a.Position,new WorldPoint(0,0),a),"Phase 18 overlap recovery cannot deepen overlap or cross scenery");
